const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/tagtimeout";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "vitest.config.mjs"),
  "export default { test: { tags: [{ name: 'slow', timeout: 10000 }] } }\n");
fs.writeFileSync(path.join(dir, "slow.test.mjs"), [
  "import { describe, test } from 'vitest'",
  "describe('suite', { timeout: 500 }, () => {",
  "  test('waits', { tags: ['slow'] }, async () => { await new Promise(r => setTimeout(r, 1500)) })",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--reporter=json", "--outputFile=report.json"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
const reportFile = path.join(dir, "report.json");
if (!fs.existsSync(reportFile)) {
  console.error("ERROR: vitest wrote no JSON report (exit " + r.status + ")");
  process.exit(2);
}
const report = JSON.parse(fs.readFileSync(reportFile, "utf8"));
const results = (report.testResults || []).flatMap(f => f.assertionResults || []);
const t = results.find(a => a.title === "waits");
if (!t) {
  console.error("ERROR: test waits not found in report");
  process.exit(2);
}
const msgs = (t.failureMessages || []).join("\n");
console.log("status " + t.status + "; " + msgs);
if (t.status === "passed" && r.status === 0) {
  console.log("PASS: tag timeout 10000 overrode suite timeout 500");
  process.exit(0);
}
if (t.status === "failed" && /timed out in 500ms/i.test(msgs)) {
  console.error("FAIL: suite timeout 500 overrode the tag timeout 10000 and the test timed out");
  process.exit(1);
}
console.error("ERROR: unexpected result (status " + t.status + ", exit " + r.status + ")");
process.exit(2);

